public function updatePosition($way, $position)
{
    $res = Db::executeS('SELECT id_category, position FROM category WHERE id_parent = '.$this->id_parent.' ORDER BY position ASC');
    ... $increment = ($way ? '- 1' : '+ 1');
    Db::execute('UPDATE category SET position = position '.$increment.' WHERE position > '.$this->position);
    return Db::execute('UPDATE category SET position = '.$position.' WHERE id_category = '.$this->id);
}
